SELECT 'gongkao', '现期倍数', 'kp-xingce-data-multiple-current', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "现期倍数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "两个现期绝对量之间的除法比对。没有任何花招，最纯粹的算术题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“2023年，A 是 B 的多少倍？”或“A 比 B 多几倍？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 是几倍：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A ÷ B"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 多几倍：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " A ÷ B - 1"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干] --> B{问的是'是几倍'还是'多几倍'?}\nB -- 是几倍 --> C[列式 A / B]\nB -- 多几倍 --> D[列式 A / B - 1]\nC --> E[统一量级单位]\nD --> E\nE --> F[截位直除得出答案]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年甲省GDP为 12.5 亿元，乙省为 300 万元。问甲省GDP比乙省多多少倍？选项：A. 4.1  B. 40.6  C. 416  D. 415"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "咬文嚼字：问的是“多几倍”，所以是 A/B - 1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "统一量级：甲是 12.5 亿元，乙是 300 万元。先把甲翻译成 125000 万元。否则必定死在数量级上。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算商：125000 ÷ 300 = 1250 ÷ 3 ≈ 416.6 倍。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "减去 1：416.6 - 1 = 415.6 倍。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 D。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一字之差谬以千里：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“是 3 倍” 和 “多 2 倍” 是同一个意思。命题人特别喜欢在选项里同时放上 416 和 415 两个选项，一旦你看漏了那个“多”字，就直接跳进了完美的陷阱。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看到倍数题，第一时间拿笔把“是”或“多”字圈成重重的黑圈，时刻提醒自己要不要减 1。"}]}]}$$ AS jsonb), NULL, '现期倍数的核心考点与实战推导。', category_node.id, CAST('["资料分析", "现期倍数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_multiple_current", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
